  "Delete this session?": { es: "¿Eliminar esta sesión?", fr: "Supprimer cette séance ?", de: "Diese Einheit löschen?", ja: "このセッションを削除しますか？", ko: "이 세션을 삭제할까요?", zh: "删除这次课程？" },
  "Delete this user's space “{0}”? Everything inside it will be removed.": { es: "¿Eliminar el espacio «{0}» de este usuario? Todo su contenido se borrará.", fr: "Supprimer l'espace « {0} » de cet utilisateur ? Tout son contenu sera effacé.", de: "Den Bereich „{0}“ dieses Benutzers löschen? Alle Inhalte darin werden entfernt.", ja: "このユーザーのスペース「{0}」を削除しますか？中の内容はすべて削除されます。", ko: "이 사용자의 공간 '{0}'을(를) 삭제할까요? 안의 내용이 모두 삭제됩니다.", zh: "删除该用户的空间“{0}”？其中的所有内容都会被删除。" },
  "Delete “{0}” from this user's space?": { es: "¿Eliminar «{0}» del espacio de este usuario?", fr: "Supprimer « {0} » de l'espace de cet utilisateur ?", de: "„{0}“ aus dem Bereich dieses Benutzers löschen?", ja: "このユーザーのスペースから「{0}」を削除しますか？", ko: "이 사용자의 공간에서 '{0}'을(를) 삭제할까요?", zh: "从该用户的空间中删除“{0}”？" },
  "Delete “{0}”?": { es: "¿Eliminar «{0}»?", fr: "Supprimer « {0} » ?", de: "„{0}“ löschen?", ja: "「{0}」を削除しますか？", ko: "'{0}'을(를) 삭제할까요?", zh: "删除“{0}”？" },
  "Demote to User": { es: "Degradar a Usuario", fr: "Rétrograder en Utilisateur", de: "Zu Benutzer herabstufen", ja: "ユーザーに降格", ko: "사용자로 강등", zh: "降为普通用户" },
  "Disconnect": { es: "Desconectar", fr: "Déconnecter", de: "Trennen", ja: "切断", ko: "연결 해제", zh: "断开连接" },
  "Dismiss notification": { es: "Descartar notificación", fr: "Fermer la notification", de: "Benachrichtigung schließen", ja: "通知を閉じる", ko: "알림 닫기", zh: "关闭通知" },
  "Donation amount (VND)": { es: "Cantidad de la donación (VND)", fr: "Montant du don (VND)", de: "Spendenbetrag (VND)", ja: "寄付金額（VND）", ko: "기부 금액 (VND)", zh: "捐赠金额（越南盾）" },
  "Donation bank account (for QR codes)": { es: "Cuenta bancaria para donaciones (para códigos QR)", fr: "Compte bancaire des dons (pour les codes QR)", de: "Spendenkonto (für QR-Codes)", ja: "寄付受取口座（QRコード用）", ko: "기부 수령 계좌 (QR 코드용)", zh: "捐赠收款账户（用于二维码）" },
  "Donation transfer QR code": { es: "Código QR de transferencia de donación", fr: "Code QR de virement du don", de: "QR-Code für die Spendenüberweisung", ja: "寄付送金QRコード", ko: "기부 송금 QR 코드", zh: "捐赠转账二维码" },
  "Donations": { es: "Donaciones", fr: "Dons", de: "Spenden", ja: "寄付", ko: "기부", zh: "捐赠" },
  "Donations: {0} received across {1} transactions, {2} still pending confirmation. Admin operations live in their own items in the sidebar (Admin group).": { es: "Donaciones: {0} recibidos en {1} transacciones, {2} aún pendientes de confirmación. Las operaciones de administración están en sus propios apartados de la barra lateral (grupo Administración).", fr: "Dons : {0} reçus sur {1} transactions, {2} encore en attente de confirmation. Les opérations d'administration ont leurs propres entrées dans la barre latérale (groupe Admin).", de: "Spenden: {0} erhalten in {1} Transaktionen, {2} warten noch auf Bestätigung. Admin-Vorgänge haben eigene Einträge in der Seitenleiste (Gruppe Admin).", ja: "寄付：{1}件の取引で{0}を受領、{2}件が確認待ちです。管理操作はサイドバー（管理グループ）の各項目にあります。", ko: "기부: 거래 {1}건에서 {0} 수령, {2}건이 확인 대기 중입니다. 관리 작업은 사이드바(관리 그룹)의 각 항목에 있습니다.", zh: "捐赠：共 {1} 笔交易已收到 {0}，{2} 笔待确认。管理操作位于侧边栏（管理组）的各自条目中。" },
  "Donations customers start in the app appear here as “Pending”, with their creation date and time; confirm once the money arrives. Update the receiving bank account so the app can generate QR codes with the amount and transaction code pre-filled. Totals are never public.": { es: "Las donaciones que los clientes inician en la app aparecen aquí como «Pendientes», con su fecha y hora de creación; confírmalas cuando llegue el dinero. Actualiza la cuenta receptora para que la app genere códigos QR con el importe y el código de transacción ya rellenados. Los totales nunca son públicos.", fr: "Les dons lancés par les clients dans l'app apparaissent ici comme « En attente », avec leur date et heure de création ; confirme-les à l'arrivée de l'argent. Mets à jour le compte de réception pour que l'app génère des QR avec le montant et le code de transaction préremplis. Les totaux ne sont jamais publics.", de: "Spenden, die Kunden in der App starten, erscheinen hier als „Ausstehend“ mit Erstellungsdatum und -zeit; bestätige sie, sobald das Geld da ist. Aktualisiere das Empfängerkonto, damit die App QR-Codes mit vorausgefülltem Betrag und Transaktionscode erzeugt. Summen sind nie öffentlich.", ja: "お客様がアプリで開始した寄付は、作成日時とともにここに「保留中」として表示されます。入金されたら確認してください。受取口座を更新すると、金額と取引コードが入力済みのQRコードをアプリが生成します。合計は公開されません。", ko: "고객이 앱에서 시작한 기부는 생성 날짜와 시간과 함께 여기에 '대기 중'으로 표시됩니다. 돈이 도착하면 확인하세요. 수령 계좌를 업데이트하면 앱이 금액과 거래 코드가 미리 입력된 QR 코드를 생성합니다. 총액은 공개되지 않습니다.", zh: "客户在应用内发起的捐赠会以“待确认”状态显示在这里，附创建日期和时间；款项到账后请确认。更新收款账户后，应用可生成已预填金额和交易代码的二维码。总额从不公开。" },
  "Donations received": { es: "Donaciones recibidas", fr: "Dons reçus", de: "Erhaltene Spenden", ja: "受け取った寄付", ko: "받은 기부금", zh: "已收到的捐赠" },
  "Done": { es: "Enviado", fr: "Envoyé", de: "Fertig", ja: "送信済み", ko: "전송 완료", zh: "已发送" },
  "Done! You scored {0}/{1}.": { es: "¡Terminado! Acertaste {0}/{1}.", fr: "Terminé ! Tu as réussi {0}/{1}.", de: "Fertig! Du hast {0}/{1} richtig.", ja: "完了！{0}/{1}正解でした。", ko: "완료! {0}/{1}개를 맞혔어요.", zh: "完成！你答对了 {0}/{1}。" },
