  "End time": { es: "Hora de fin", fr: "Heure de fin", de: "Endzeit", ja: "終了時刻", ko: "종료 시간", zh: "结束时间" },
  "English word": { es: "Palabra en inglés", fr: "Mot en anglais", de: "Englisches Wort", ja: "英単語", ko: "영어 단어", zh: "英语单词" },
  "Enter a new name for the space.": { es: "Introduce un nombre nuevo para el espacio.", fr: "Saisis un nouveau nom pour l'espace.", de: "Gib einen neuen Namen für den Bereich ein.", ja: "スペースの新しい名前を入力してください。", ko: "공간의 새 이름을 입력하세요.", zh: "请输入空间的新名称。" },
  "Enter the English word first.": { es: "Primero introduce la palabra en inglés.", fr: "Saisis d'abord le mot en anglais.", de: "Gib zuerst das englische Wort ein.", ja: "まず英単語を入力してください。", ko: "먼저 영어 단어를 입력하세요.", zh: "请先输入英语单词。" },
