  "Give your note a title.": { es: "Ponle un título a tu nota.", fr: "Donne un titre à ta note.", de: "Gib deiner Notiz einen Titel.", ja: "メモにタイトルを付けてください。", ko: "메모에 제목을 입력하세요.", zh: "请为笔记起个标题。" },
  "Go to the feature store to create your first space": { es: "Ve a la tienda de funciones para crear tu primer espacio", fr: "Va dans le catalogue de fonctions pour créer ton premier espace", de: "Öffne den Funktionskatalog, um deinen ersten Bereich zu erstellen", ja: "機能ストアで最初のスペースを作成", ko: "기능 스토어에서 첫 공간 만들기", zh: "前往功能商店创建你的第一个空间" },
