  "Name your space first.": { es: "Primero ponle un nombre a tu espacio.", fr: "Donne d'abord un nom à ton espace.", de: "Gib deinem Bereich zuerst einen Namen.", ja: "まずスペースに名前を付けてください。", ko: "먼저 공간 이름을 입력하세요.", zh: "请先为空间命名。" },
