  "New password needs at least 6 characters.": { es: "La contraseña nueva necesita al menos 6 caracteres.", fr: "Le nouveau mot de passe doit contenir au moins 6 caractères.", de: "Das neue Passwort braucht mindestens 6 Zeichen.", ja: "新しいパスワードは6文字以上必要です。", ko: "새 비밀번호는 6자 이상이어야 합니다.", zh: "新密码至少需要 6 个字符。" },
  "Next": { es: "Adelante", fr: "Suivant", de: "Weiter", ja: "次へ", ko: "다음", zh: "下一个" },
  "No cards yet. Add a word below or from the Vocabulary notebook.": { es: "Aún no hay tarjetas. Añade una palabra abajo o desde el Cuaderno de vocabulario.", fr: "Aucune carte pour l'instant. Ajoute un mot ci-dessous ou depuis le Carnet de vocabulaire.", de: "Noch keine Karten. Füge unten oder aus dem Vokabelheft ein Wort hinzu.", ja: "まだカードがありません。下から、または単語ノートから単語を追加してください。", ko: "아직 카드가 없어요. 아래에서 단어를 추가하거나 단어장에서 추가하세요.", zh: "暂无卡片。在下方添加单词，或从词汇手册添加。" },
  "No contact links yet.": { es: "Aún no hay enlaces de contacto.", fr: "Aucun lien de contact pour l'instant.", de: "Noch keine Kontaktlinks.", ja: "連絡先リンクはまだありません。", ko: "아직 연락처 링크가 없어요.", zh: "暂无联系链接。" },
  "No donations yet.": { es: "Aún no hay donaciones.", fr: "Aucun don pour l'instant.", de: "Noch keine Spenden.", ja: "寄付はまだありません。", ko: "아직 기부가 없어요.", zh: "暂无捐赠。" },
  "No events.": { es: "Sin eventos.", fr: "Aucun événement.", de: "Keine Termine.", ja: "イベントはありません。", ko: "일정이 없어요.", zh: "没有事件。" },
  "No extra permissions": { es: "Sin permisos extra", fr: "Aucune permission supplémentaire", de: "Keine zusätzlichen Berechtigungen", ja: "追加の権限なし", ko: "추가 권한 없음", zh: "无额外权限" },
  "No goals yet. Create your first goal.": { es: "Aún no hay metas. Crea tu primera meta.", fr: "Aucun objectif pour l'instant. Crée ton premier objectif.", de: "Noch keine Ziele. Erstelle dein erstes Ziel.", ja: "目標はまだありません。最初の目標を作成しましょう。", ko: "아직 목표가 없어요. 첫 목표를 만들어 보세요.", zh: "暂无目标。创建你的第一个目标吧。" },
  "No notes yet.": { es: "Aún no hay notas.", fr: "Aucune note pour l'instant.", de: "Noch keine Notizen.", ja: "メモはまだありません。", ko: "아직 메모가 없어요.", zh: "暂无笔记。" },
  "No password reset requests yet.": { es: "Aún no hay solicitudes de restablecimiento de contraseña.", fr: "Aucune demande de réinitialisation pour l'instant.", de: "Noch keine Passwort-Zurücksetzungsanfragen.", ja: "パスワードリセットの申請はまだありません。", ko: "아직 비밀번호 재설정 요청이 없어요.", zh: "暂无密码重置请求。" },
  "No saved sessions yet.": { es: "Aún no hay sesiones guardadas.", fr: "Aucune séance enregistrée pour l'instant.", de: "Noch keine gespeicherten Einheiten.", ja: "保存されたセッションはまだありません。", ko: "아직 저장된 세션이 없어요.", zh: "暂无已保存的课程。" },
  "No sessions on this date.": { es: "No hay sesiones en esta fecha.", fr: "Aucune séance à cette date.", de: "Keine Einheiten an diesem Datum.", ja: "この日のセッションはありません。", ko: "이 날짜에는 세션이 없어요.", zh: "这一天没有课程。" },
  "No sessions yet.": { es: "Aún no hay sesiones.", fr: "Aucune séance pour l'instant.", de: "Noch keine Einheiten.", ja: "セッションはまだありません。", ko: "아직 세션이 없어요.", zh: "暂无课程。" },
  "No transactions match the filter.": { es: "Ninguna transacción coincide con el filtro.", fr: "Aucune transaction ne correspond au filtre.", de: "Keine Transaktion entspricht dem Filter.", ja: "フィルターに一致する取引はありません。", ko: "필터와 일치하는 거래가 없어요.", zh: "没有符合筛选条件的交易。" },
  "No words yet.": { es: "Aún no hay palabras.", fr: "Aucun mot pour l'instant.", de: "Noch keine Wörter.", ja: "単語はまだありません。", ko: "아직 단어가 없어요.", zh: "暂无单词。" },
  "No words yet. Add your first word.": { es: "Aún no hay palabras. Añade tu primera palabra.", fr: "Aucun mot pour l'instant. Ajoute ton premier mot.", de: "Noch keine Wörter. Füge dein erstes Wort hinzu.", ja: "単語はまだありません。最初の単語を追加しましょう。", ko: "아직 단어가 없어요. 첫 단어를 추가해 보세요.", zh: "暂无单词。添加你的第一个单词吧。" },
  "Not connected": { es: "No conectado", fr: "Non connecté", de: "Nicht verbunden", ja: "未接続", ko: "연결 안 됨", zh: "未连接" },
  "Not quite — listen again.": { es: "Casi — escucha de nuevo.", fr: "Pas tout à fait — réécoute.", de: "Nicht ganz — hör noch einmal hin.", ja: "惜しい！もう一度聞いてみましょう。", ko: "아쉬워요 — 다시 들어 보세요.", zh: "还不对——再听一遍。" },
  "Not quite. ": { es: "Casi. ", fr: "Pas tout à fait. ", de: "Nicht ganz. ", ja: "惜しい！", ko: "아쉬워요. ", zh: "还不对。" },
  "Not set": { es: "Sin definir", fr: "Non défini", de: "Nicht festgelegt", ja: "未設定", ko: "설정 안 됨", zh: "未设置" },
  "Not yet · tomorrow": { es: "Todavía no · mañana", fr: "Pas encore · demain", de: "Noch nicht · morgen", ja: "まだ · 明日", ko: "아직 · 내일", zh: "还没记住 · 明天" },
  "Note": { es: "Nota", fr: "Note", de: "Notiz", ja: "メモ", ko: "메모", zh: "备注" },
