  "Notes": { es: "Notas", fr: "Notes", de: "Notizen", ja: "メモ", ko: "메모", zh: "笔记" },
  "Nothing due today. Great job!": { es: "Nada por repasar hoy. ¡Buen trabajo!", fr: "Rien à réviser aujourd'hui. Beau travail !", de: "Heute nichts zu wiederholen. Stark!", ja: "今日復習するものはありません。よくできました！", ko: "오늘 복습할 단어가 없어요. 잘했어요!", zh: "今天没有要复习的内容。做得好！" },
  "Nothing on this day.": { es: "Nada en este día.", fr: "Rien ce jour-là.", de: "An diesem Tag ist nichts.", ja: "この日は何もありません。", ko: "이 날짜에는 아무것도 없어요.", zh: "这一天没有安排。" },
  "Nothing scheduled in the next 30 days. Tap “Add event” to plan your first study session.": { es: "Nada programado en los próximos 30 días. Toca «Añadir evento» para planificar tu primera sesión de estudio.", fr: "Rien de prévu dans les 30 prochains jours. Touche « Ajouter un événement » pour planifier ta première séance d'étude.", de: "In den nächsten 30 Tagen ist nichts geplant. Tippe auf „Termin hinzufügen“, um deine erste Lerneinheit zu planen.", ja: "今後30日間の予定はありません。「イベントを追加」をタップして最初の学習セッションを計画しましょう。", ko: "앞으로 30일 동안 예정된 일정이 없어요. '일정 추가'를 눌러 첫 학습 세션을 계획하세요.", zh: "未来 30 天没有安排。点击“添加事件”来规划你的第一节学习课程。" },
  "Notify when time is up": { es: "Avisar cuando se acabe el tiempo", fr: "Notifier à la fin du temps", de: "Benachrichtigen, wenn die Zeit um ist", ja: "時間終了時に通知", ko: "시간 종료 시 알림", zh: "时间结束时通知" },
  "Off": { es: "Desactivado", fr: "Désactivé", de: "Aus", ja: "オフ", ko: "꺼짐", zh: "已关闭" },
