  "Save event": { es: "Guardar evento", fr: "Enregistrer l'événement", de: "Termin speichern", ja: "イベントを保存", ko: "일정 저장", zh: "保存事件" },
  "Save login information": { es: "Guardar información de acceso", fr: "Enregistrer les infos de connexion", de: "Anmeldeinformationen speichern", ja: "ログイン情報を保存", ko: "로그인 정보 저장", zh: "保存登录信息" },
