  "Saved bank account": { es: "Cuenta bancaria guardada", fr: "Compte bancaire enregistré", de: "Gespeichertes Bankkonto", ja: "保存済みの銀行口座", ko: "저장된 은행 계좌", zh: "已保存的银行账户" },
