  "Saved successfully!": { es: "¡Guardado correctamente!", fr: "Enregistré avec succès !", de: "Erfolgreich gespeichert!", ja: "保存しました！", ko: "성공적으로 저장되었습니다!", zh: "保存成功！" },
  "Saved.": { es: "Guardado.", fr: "Enregistré.", de: "Gespeichert.", ja: "保存しました。", ko: "저장되었습니다.", zh: "已保存。" },
