  "Search transactions": { es: "Buscar transacciones", fr: "Rechercher des transactions", de: "Transaktionen suchen", ja: "取引を検索", ko: "거래 검색", zh: "搜索交易" },
  "Search transactions (code / donor)": { es: "Buscar transacciones (código / donante)", fr: "Rechercher des transactions (code / donateur)", de: "Transaktionen suchen (Code / Spender)", ja: "取引を検索（コード / 寄付者）", ko: "거래 검색 (코드 / 기부자)", zh: "搜索交易（代码 / 捐赠者）" },
  "Search words…": { es: "Buscar palabras…", fr: "Rechercher des mots…", de: "Wörter suchen…", ja: "単語を検索…", ko: "단어 검색…", zh: "搜索单词……" },
  "Select gender": { es: "Selecciona el género", fr: "Choisis le genre", de: "Geschlecht wählen", ja: "性別を選択", ko: "성별 선택", zh: "选择性别" },
  "Session saved to the list below.": { es: "Sesión guardada en la lista de abajo.", fr: "Séance enregistrée dans la liste ci-dessous.", de: "Einheit in der Liste unten gespeichert.", ja: "セッションを下のリストに保存しました。", ko: "세션이 아래 목록에 저장되었습니다.", zh: "课程已保存到下方列表。" },
  "Session title": { es: "Título de la sesión", fr: "Titre de la séance", de: "Titel der Einheit", ja: "セッション名", ko: "세션 제목", zh: "课程标题" },
