  "Settings: profile, password, language, theme and Google Sheet": { es: "Ajustes: perfil, contraseña, idioma, tema y Google Sheet", fr: "Réglages : profil, mot de passe, langue, thème et Google Sheet", de: "Einstellungen: Profil, Passwort, Sprache, Design und Google Sheet", ja: "設定：プロフィール、パスワード、言語、テーマ、Googleスプレッドシート", ko: "설정: 프로필, 비밀번호, 언어, 테마, Google Sheet", zh: "设置：个人资料、密码、语言、主题和 Google 表格" },
  "Show the Donate section to users": { es: "Mostrar la sección de donaciones a los usuarios", fr: "Afficher la section Dons aux utilisateurs", de: "Spendenbereich für Benutzer anzeigen", ja: "寄付セクションをユーザーに表示", ko: "사용자에게 기부 섹션 표시", zh: "向用户显示捐赠板块" },
  "Show the QR to transfer": { es: "Mostrar el QR para transferir", fr: "Afficher le QR pour transférer", de: "QR zum Überweisen anzeigen", ja: "送金用QRを表示", ko: "이체용 QR 표시", zh: "显示转账二维码" },
  "Sign out of this account": { es: "Cerrar sesión en esta cuenta", fr: "Se déconnecter de ce compte", de: "Von diesem Konto abmelden", ja: "このアカウントからログアウト", ko: "이 계정에서 로그아웃", zh: "退出此账号" },
  "Skip — I'll set my own goal later": { es: "Omitir — pondré mi propia meta después", fr: "Passer — je définirai mon propre objectif plus tard", de: "Überspringen — ich setze mein Ziel später selbst", ja: "スキップ — 目標は後で自分で設定します", ko: "건너뛰기 — 목표는 나중에 직접 설정할게요", zh: "跳过——稍后我自己设定目标" },
  "Something went wrong. Please try again.": { es: "Algo salió mal. Inténtalo de nuevo.", fr: "Un problème est survenu. Réessaie.", de: "Etwas ist schiefgelaufen. Bitte versuche es erneut.", ja: "問題が発生しました。もう一度お試しください。", ko: "문제가 발생했습니다. 다시 시도해 주세요.", zh: "出了点问题。请重试。" },
  "Space limit, showcase numbers, suggested goals and feature toggles": { es: "Límite de espacios, cifras destacadas, metas sugeridas y activación de funciones", fr: "Limite d'espaces, chiffres vitrine, objectifs suggérés et activation des fonctions", de: "Bereichslimit, Kennzahlen, Zielvorschläge und Funktionsschalter", ja: "スペース上限、ショーケース数値、おすすめ目標、機能のオン/オフ", ko: "공간 한도, 쇼케이스 수치, 추천 목표, 기능 켜기/끄기", zh: "空间上限、展示数据、推荐目标和功能开关" },
