export function tx(lang: Lang, vi: string, en: string): string {
  if (lang === "vi") return vi;
  if (lang === "en") return en;
  return EXTRA[en]?.[lang] ?? en;
}

// Like tx(), but the strings are templates with {0}, {1}, … placeholders
// filled from args (numbers are formatted with the plain String() form,
// matching the previous inline template literals).
export function txf(lang: Lang, vi: string, en: string, ...args: (string | number)[]): string {
  const tpl = tx(lang, vi, en);
  return tpl.replace(/\{(\d+)\}/g, (m, i: string) => {
    const v = args[Number(i)];
    return v === undefined ? m : String(v);
  });
}

